REPLACE INTO `sys_config` VALUES (null, 'report_freemarker_common', '<#function convertNumber value unitType step>\r\n    <#local numberUnit = [\"\", \"K\", \"M\", \"G\", \"T\", \"P\", \"E\"]>\r\n    <#local byteUnit = [\"B\", \"KB\", \"MB\", \"GB\", \"TB\", \"PB\", \"EB\"]>\r\n    <#local byteRateUnit = [\"bps\", \"Kbps\", \"Mbps\", \"Gbps\", \"Tbps\", \"Pbps\", \"Ebps\"]>\r\n    <#local currentUnit = numberUnit >\r\n    <#local tempValue = value>\r\n    <#local stepAddOne = false>\r\n    <#if value?string?contains(\'-\')>\r\n        <#return value>\r\n    <#else>\r\n        <#if unitType == \"byte\">\r\n            <#local currentUnit = byteUnit>\r\n            <#if value gt 1024>\r\n                <#local tempValue = value / 1024>\r\n                <#local stepAddOne = true>\r\n            </#if>\r\n        <#elseif unitType == \"bps\">\r\n            <#local currentUnit = byteRateUnit>\r\n            <#if value gt 1000>\r\n                <#local tempValue = value / 1000>\r\n                <#local stepAddOne = true>\r\n            </#if>\r\n        <#elseif unitType == \"number\">\r\n            <#local currentUnit = numberUnit>\r\n        </#if>\r\n        <#list currentUnit as unit>\r\n            <#if tempValue / step gt 1>\r\n                <#local tempValue = tempValue / step>\r\n            <#else>\r\n                <#if stepAddOne == true>\r\n                    <#return tempValue?string(\"0.##\") + \" \" + currentUnit[unit_index + 1]>\r\n                <#else>\r\n                    <#return tempValue?string(\"0.##\") + \" \" + currentUnit[unit_index]>\r\n                </#if>\r\n            </#if>\r\n        </#list>\r\n    </#if>\r\n</#function>\r\n\r\n<#function getChainRatio value key param currentList prevList>\r\n    <#if value?string?contains(\'-\')>\r\n        <#return value>\r\n    </#if>\r\n    <#local currentData=-1>\r\n    <#local prevData=-1>\r\n\r\n    <#local chainRatio=\'\'>\r\n\r\n    <#list currentList as val>\r\n        <#if val[key]==value>\r\n            <#local currentData=val[param]?eval>\r\n        </#if>\r\n    </#list>\r\n    <#list prevList as pVal>\r\n        <#if pVal[key]==value>\r\n            <#local prevData=pVal[param]?eval>\r\n        </#if>\r\n    </#list>\r\n\r\n    <#if currentData gt 0 && prevData gt 0>\r\n        <#local currentRatio=(currentData - prevData) / prevData * 100>\r\n        <#local chainRatio+=currentRatio?string(\"0.##\") + \'%\'>\r\n    <#else>\r\n        <#local chainRatio+=\'-\'>\r\n    </#if>\r\n\r\n    <#return chainRatio>\r\n</#function>\r\n\r\n\r\n<#function findRecordByName value key data1 list>\r\n    <#local findIndex = -1>\r\n    <#if value?string?contains(\'-\')>\r\n        <#return findIndex>\r\n    </#if>\r\n    <#list list as d>\r\n        <#if d[key] == value>\r\n            <#local findIndex = d_index>\r\n        </#if>\r\n    </#list>\r\n    <#return findIndex>\r\n</#function>\r\n\r\n<#function convertTime value>\r\n    <#local timeUnit = [\r\n    { \"unit\": \'ms\', \"step\": 1 },\r\n    { \"unit\": \'s\', \"step\": 1000 },\r\n    { \"unit\": \'m\', \"step\": 60 },\r\n    { \"unit\": \'h\', \"step\": 60 },\r\n    { \"unit\": \'d\', \"step\": 24 }\r\n    ]>\r\n    <#local i = 0>\r\n    <#local temp = value>\r\n    <#if value?string?contains(\'-\')>\r\n        <#return value>\r\n    <#else>\r\n        <#list timeUnit as unit>\r\n            <#if (temp >= unit.step && i == unit_index)>\r\n                <#local temp = temp / unit.step>\r\n                <#local i = i+1>\r\n            </#if>\r\n        </#list>\r\n        <#if (i > 0)>\r\n            <#return temp?string(\"0.##\") + \" \" + timeUnit[i-1].unit>\r\n        <#else>\r\n            <#return temp + \" \" + timeUnit[0].unit>\r\n        </#if>\r\n    </#if>\r\n</#function>\r\n\r\n<#function getFromArr array index attr type>\r\n    <#if index == -1>\r\n        <#return \'-\'>\r\n    </#if>\r\n    <#if array?size gt index && array[index][attr]?? && type?lower_case?contains(\"number\")>\r\n        <#return array[index][attr]?number>\r\n    <#elseif array?size gt index && array[index][attr]?? && type?lower_case?contains(\"string\")>\r\n        <#return array[index][attr]?string>\r\n    <#else>\r\n        <#return \'-\'>\r\n    </#if>\r\n</#function>\r\n\r\n<#function getFromObj object attr type>\r\n    <#if object[attr]?? && type?lower_case?contains(\"number\")>\r\n        <#return object[attr]?number>\r\n    <#elseif object[attr]?? && type?lower_case?contains(\"string\")>\r\n    	<#if object[attr]==\'\'>\r\n    		<#return \'unknow\'>\r\n    	<#else>\r\n    		<#return object[attr]?string>\r\n    	</#if>\r\n    <#else>\r\n        <#return \'-\'>\r\n    </#if>\r\n</#function>\r\n\r\n<#function chainRatio value preValue>\r\n    <#if !value?string?contains(\'-\') && !preValue?string?contains(\'-\') && preValue!=0>\r\n        <#return ((value - preValue) / preValue * 100)?string(\"#.##\") + \'%\'>\r\n    <#else>\r\n        <#return \'-\'>\r\n    </#if>\r\n</#function>\r\n\r\n<#function convertPercent value>\r\n    <#if !value?string?contains(\'-\')>\r\n        <#return (value * 100)?string(\"#.##\") + \'%\'>\r\n    <#else>\r\n        <#return \'-\'>\r\n    </#if>\r\n</#function>\r\n\r\n<#function proportion part Total>\r\n    <#if !part?string?contains(\'-\') && !Total?string?contains(\'-\') && Total!=0>\r\n        <#return (part / Total * 100)?string(\"#.##\") + \'%\'>\r\n    <#else>\r\n        <#return \'-\'>\r\n    </#if>\r\n</#function>\r\n\r\n<#function jsGetNumFromArr array index attr>\r\n    <#if array?size gt index && array[index][attr]??>\r\n        <#return array[index][attr]?number>\r\n    <#else>\r\n        <#return 0>\r\n    </#if>\r\n</#function>\r\n\r\n<#function jsGetNumFromObj object attr>\r\n    <#if object[attr]??>\r\n        <#return object[attr]?number>\r\n    <#else>\r\n        <#return 0>\r\n    </#if>\r\n</#function>\r\n', 1, NULL);
REPLACE INTO `sys_config` VALUES (null, 'report_js_common', '/** 内置js begin */\r\n/* 由于js的number精度最多到8PB-1，而实际流量达百PB级,\r\n  所以对于byte类型数据，在java(freemarker)中除以1024后再处理；时间、数量、百分比等其他类型不变。\r\n*/\r\nvar chartColor = [\'rgb(132,202,230)\', \'rgb(88,176,209)\', \'rgb(133,221,214)\', \'rgb(245,184,136)\',\r\n  \'rgb(235,198,90)\', \'rgb(237,157,138)\', \'rgb(140,206,213)\', \'rgb(174,214,222)\',\r\n  \'rgb(153,96,180)\', \'rgb(254,166,158)\', \'rgb(87,203,172)\', \'rgb(99,182,172)\', \'rgb(180,208,148)\']\r\nvar barLineColor = {\r\n  bar1: \'rgb(59,162,201)\',\r\n  bar2: chartColor[2],\r\n  line1: \'rgb(59,162,201)\',\r\n  line2: chartColor[2],\r\n  line3: chartColor[10]\r\n}\r\nvar directionChartColor = [\'rgb(88,176,209)\', \'rgb(180,208,148)\', \'rgb(140,206,213)\', \'rgb(235,198,90)\', \'rgb(174,214,222)\', \'rgb(237,157,138)\']\r\nvar unitTypes = {\r\n  time: \'time\',\r\n  number: \'number\',\r\n  byte: \'byte\',\r\n  bps: \'bps\',\r\n  string: \'string\',\r\n  percent: \'percent\'\r\n}\r\n\r\nvar numberUnit = [\'\', \'K\', \'M\', \'G\', \'T\', \'P\', \'E\']\r\nvar byteUnit = [\'B\', \'KB\', \'MB\', \'GB\', \'TB\', \'PB\', \'EB\']\r\nvar bpsUnit = [\'bps\', \'Kbps\', \'Mbps\', \'Gbps\', \'Tbps\', \'Pbps\', \'Ebps\']\r\nvar timeUnit = [ // 时间单位步进倍数，以ms为基数\r\n  { unit: \'ms\', step: 1 },\r\n  { unit: \'s\', step: 1000 },\r\n  { unit: \'m\', step: 60 },\r\n  { unit: \'h\', step: 60 },\r\n  { unit: \'d\', step: 24 }\r\n]\r\nfunction asciiCompute (num, offset = 0, ascii = 1000, units, dot = 2) {\r\n  if (!num && num !== 0 && num !== \'0\') {\r\n    return [\'\', \'\']\r\n  }\r\n  num = Number(num)\r\n  var carry = 0\r\n  if (num > 1) {\r\n    var log = Math.log(num) / Math.log(ascii)\r\n    carry = parseInt(log)\r\n    num = num / Math.pow(ascii, carry)\r\n  }\r\n  if (Number.isInteger(num)) {\r\n    return [num, units[carry + offset]]\r\n  } else {\r\n    return [num.toFixed(dot), units[carry + offset]]\r\n  }\r\n}\r\nfunction numberUnitConvert (value, sourceUnit = \'\', targetUnit, dot = 2) {\r\n  return asciiCompute(value, numberUnit.indexOf(sourceUnit), 1000, numberUnit, dot)\r\n}\r\nfunction byteUnitConvert (value, sourceUnit = \'B\', targetUnit, dot = 2) {\r\n  return asciiCompute(value, byteUnit.indexOf(sourceUnit), 1024, byteUnit, dot)\r\n}\r\nfunction bpsUnitConvert (value, sourceUnit = \'bps\', targetUnit, dot = 2) {\r\n  return asciiCompute(value, bpsUnit.indexOf(sourceUnit), 1000, bpsUnit, dot)\r\n}\r\nfunction timeUnitFormatter (time, sourceUnit = \'ms\', targetUnit, dot = 2) {\r\n  if (time === \'\' || time instanceof Array || isNaN(time)) {\r\n    return [0, sourceUnit]\r\n  }\r\n  var sourceIndex = -1\r\n  var targetIndex = -1\r\n  timeUnit.forEach((t, i) => {\r\n    sourceUnit === t.unit && (sourceIndex = i)\r\n    targetUnit && targetUnit === t.unit && (targetIndex = i)\r\n  })\r\n  var multi = 1\r\n  var result = parseFloat(time)\r\n  if (targetIndex < 0) {\r\n    while (sourceIndex < timeUnit.length - 1 && result > timeUnit[sourceIndex + 1].step) {\r\n      sourceIndex++\r\n      multi = timeUnit[sourceIndex].step\r\n      result /= multi\r\n    }\r\n    return [multi === 1 ? result : result.toFixed(dot), timeUnit[sourceIndex].unit]\r\n  } else {\r\n    timeUnit.forEach((s, i) => {\r\n      if (i <= targetIndex) {\r\n        multi *= s.step\r\n      }\r\n    })\r\n    result /= multi\r\n    return [result.toFixed(dot), targetUnit]\r\n  }\r\n}\r\nfunction unitConvert (value, unitType, sourceUnit, targetUnit, dot = 2) {\r\n  if (unitType === unitTypes.string) {\r\n    if (value) {\r\n      if (typeof value === \'string\') {\r\n        return [value, \'\']\r\n      } else {\r\n        return [\'-\', \'\']\r\n      }\r\n    } else {\r\n      return [\'-\', \'\']\r\n    }\r\n  }\r\n  if (!value && value !== 0) {\r\n    return [\'-\', \'\']\r\n  } else {\r\n    switch (unitType) {\r\n      case unitTypes.time: {\r\n        return timeUnitFormatter(value, sourceUnit, targetUnit, dot)\r\n      }\r\n      case unitTypes.percent: {\r\n        return [(Number(value) * 100).toFixed(dot), \'%\']\r\n      }\r\n      case unitTypes.number: {\r\n        return numberUnitConvert(value, sourceUnit, targetUnit, dot)\r\n      }\r\n      case unitTypes.byte: {\r\n        return byteUnitConvert(value, sourceUnit, targetUnit, dot)\r\n      }\r\n      case unitTypes.bps: {\r\n        return bpsUnitConvert(value, sourceUnit, targetUnit, dot)\r\n      }\r\n    }\r\n  }\r\n}\r\nfunction getUnitType (column) {\r\n  if (column) {\r\n    switch (column.toLowerCase()) {\r\n      case \'time\': {\r\n        return unitTypes.time\r\n      }\r\n      case \'bytes\': {\r\n        return unitTypes.byte\r\n      }\r\n      case \'sessions\':\r\n      default: {\r\n        return unitTypes.number\r\n      }\r\n    }\r\n  } else {\r\n    return unitTypes.number\r\n  }\r\n}\r\n/* 深拷贝 */\r\nfunction deepClone(obj) {\r\n  //判断拷贝的obj是对象还是数组\r\n  var objClone = Array.isArray(obj) ? [] : {};\r\n  if (obj && typeof obj === \"object\") { //obj不能为空，并且是对象或者是数组 因为null也是object\r\n    for (key in obj) {\r\n      if (obj.hasOwnProperty(key)) {\r\n        if (obj[key] && typeof obj[key] === \"object\") { //obj里面属性值不为空并且还是对象，进行深度拷贝\r\n          objClone[key] = deepClone(obj[key]); //递归进行深度的拷贝\r\n        } else {\r\n          objClone[key] = obj[key]; //直接拷贝\r\n        }\r\n      }\r\n    }\r\n  }\r\n  return objClone;\r\n}\r\nfunction valueToRangeValue (value, unitType) {\r\n  var values = unitConvert(value, unitType)\r\n  if (values[0] || values[0] === 0) {\r\n    switch (unitType) {\r\n      case unitTypes.time: {\r\n        if (values[0] < 1) {\r\n          return [\'<1\', \'ms\']\r\n        }\r\n        break\r\n      }\r\n      case unitTypes.percent: {\r\n        if (values[0] < 0.01) {\r\n          return [\'<0.01\', \'%\']\r\n        }\r\n        break\r\n      }\r\n      default: break\r\n    }\r\n  }\r\n  return values\r\n}\r\n// 十位数的时间戳\r\nfunction timestampToStr (timestamp) {\r\n  var time = new Date(timestamp * 1000)\r\n  var year = time.getFullYear(),\r\n    month = time.getMonth() + 1 ,  //月份是从0开始的\r\n    day = time.getDate(),\r\n    hour = time.getHours(),\r\n    minute = time.getMinutes(),\r\n    second = time.getSeconds()\r\n  return  year + \'-\' + add0(month) + \'-\' + add0(day) + \' \' + add0(hour) + \':\' + add0(minute)\r\n}\r\nfunction add0 (m) {\r\n  return m < 10 ? \'0\' + m: m\r\n}\r\nfunction isWholeDay (_timeRange) {\r\n  var _timeRangeStrStart = timestampToStr(_timeRange[0])\r\n  var _timeOffset = _timeRange[1] - _timeRange[0]\r\n  return (_timeOffset === 86400 || _timeOffset === 86399) && _timeRangeStrStart.indexOf(\'00:00\') > -1\r\n}\r\nfunction initEchartsInstance (id, option) {\r\n  if (!option) {\r\n    option = {}\r\n  }\r\n  option.renderer = \'svg\'\r\n  return echarts.init(document.getElementById(id), null, option)\r\n}\r\nfunction checkXAxisIsEmpty(e) {\r\n  return e || \'unknown\'\r\n}\r\n// Top5 流量占比 公方法\r\nfunction barDataFormatHandling (total, preTotalList, ppreTotalList, list, preList, ppreList, oneLevelKey, twoLevelKey, dataKey) {\r\n  var seriesData = []\r\n  var prevSeriesData = []\r\n  var pprevSeriesData = []\r\n  var categoryData = []\r\n  if (total) {\r\n    var prevTotal = preTotalList.find(t => t[oneLevelKey] === total[oneLevelKey])\r\n    if (prevTotal) {\r\n      var pprevTotal = ppreTotalList.find(d => d[oneLevelKey] === prevTotal[oneLevelKey])\r\n    }\r\n    list.forEach(d => {\r\n      if (d[oneLevelKey] === total[oneLevelKey]) {\r\n        categoryData.push(d[twoLevelKey])\r\n        if (total && total[dataKey] !== 0) {\r\n          seriesData.push(d[dataKey] / total[dataKey])\r\n        } else {\r\n          seriesData.push(0)\r\n        }\r\n        var prevTwoLevel = preList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n        if (prevTwoLevel && prevTwoLevel[dataKey] && prevTotal && prevTotal[dataKey] !== 0) {\r\n          prevSeriesData.push(prevTwoLevel[dataKey] / prevTotal[dataKey])\r\n        } else {\r\n          prevSeriesData.push(0)\r\n        }\r\n\r\n        var pprevTwoLevel = ppreList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n        if (pprevTwoLevel && pprevTwoLevel[dataKey] && pprevTotal && pprevTotal[dataKey] !== 0) {\r\n          pprevSeriesData.push(pprevTwoLevel[dataKey] / pprevTotal[dataKey])\r\n        } else {\r\n          pprevSeriesData.push(0)\r\n        }\r\n      }\r\n    })\r\n  }\r\n  return {\r\n    seriesData,\r\n    prevSeriesData,\r\n    pprevSeriesData,\r\n    categoryData\r\n  }\r\n}\r\n/**\r\n * 与上方的 barDataFormatHandling 方法功能一致，皆为多series柱状图的公共方法\r\n * 提取公共方法时，并未注意到其他界面有同功能方法 barDataFormatHandling，故而导致重复，替换的话工作量较大，故暂时保留\r\n * 该方法仅用于 2022-05-23/出入口整体流量监测报告/template.html 文件中\r\n * @param params\r\n * @returns {{seriesData: *[], pprevSeriesData: *[], prevSeriesData: *[], categoryData: *[]}}\r\n */\r\nfunction get3DaysBarCharts (params) {\r\n  const categoryData = []\r\n  const seriesData = []\r\n  const prevSeriesData = []\r\n  const pprevSeriesData = []\r\n\r\n  const province = params.province\r\n  const unit = params.unit\r\n  const unit1 = params.unit1\r\n  const unit2 = params.unit2 ? params.unit2 : \'bytes\'\r\n\r\n  var prevProvince = params.prevProvince.find(t => t[unit] === province[unit])\r\n  if (prevProvince) {\r\n    var pprevProvince = params.pprevProvince.find(t => t[unit] === prevProvince[unit])\r\n  }\r\n  params.data.forEach(d => {\r\n    if (d[unit] === province[unit]) {\r\n      categoryData.push(d[unit1])\r\n      if (province && province[unit2] !== 0) {\r\n        seriesData.push(d[unit2] / province[unit2])\r\n      } else {\r\n        seriesData.push(0)\r\n      }\r\n      var prevApp = params.dataPre1st.find(p => p[unit1] === d[unit1] && p[unit] === d[unit])\r\n      if (prevApp && prevApp[unit2] && prevProvince && prevProvince[unit2] !== 0) {\r\n        prevSeriesData.push(prevApp[unit2] / prevProvince[unit2])\r\n      } else {\r\n        prevSeriesData.push(0)\r\n      }\r\n\r\n      var pprevApp = params.dataPre2st.find(p => p[unit1] === d[unit1] && p[unit] === d[unit])\r\n      if (pprevApp && pprevApp[unit2] && pprevProvince && pprevProvince[unit2] !== 0) {\r\n        pprevSeriesData.push(pprevApp[unit2] / pprevProvince[unit2])\r\n      } else {\r\n        pprevSeriesData.push(0)\r\n      }\r\n    }\r\n  })\r\n\r\n  return {\r\n    categoryData,\r\n    seriesData,\r\n    prevSeriesData,\r\n    pprevSeriesData\r\n  }\r\n}\r\n/** 内置js end */\r\n', 1, NULL);
REPLACE INTO `sys_config` VALUES (null, 'performance_endTime_interval', '86400', 1, NULL);
REPLACE INTO `sys_config` VALUES (null, 'report_style_common', '* {\r\n  box-sizing: border-box;\r\n}\r\nbody {\r\n  width: 1200px;\r\n  margin: auto;\r\n  padding-bottom: 50px;\r\n}\r\n.indent-3 {\r\n  padding-left: 50px;\r\n  padding-right: 50px;\r\n}\r\n.header1, .header2, .header3, .header4 {\r\n  font-weight: bold;\r\n}\r\n.header1 {\r\n  margin-bottom: 10px;\r\n  height: 100px;\r\n  line-height: 100px;\r\n  text-align: center;\r\n  color: white;\r\n  background-color: rgb(0,116,159);\r\n  font-size: 34px;\r\n}\r\n.header1 .header1__time {\r\n  padding-top: 6px;\r\n  padding-left: 30px;\r\n  font-size: 18px;\r\n  font-weight: normal;\r\n  font-style: italic;\r\n}\r\n.header2 {\r\n  margin: 30px 0 20px;\r\n  padding: 0 30px;\r\n  color: rgb(51,51,51);\r\n  font-size: 20px;\r\n}\r\n.header3 {\r\n  margin: 20px 0;\r\n  padding: 0 43px;\r\n  color: rgb(0,116,159);\r\n  font-size: 18px;\r\n}\r\n.header4 {\r\n  margin-bottom: 10px;\r\n  padding-left: 10px;\r\n  font-size: 14px;\r\n  color: rgba(0,0,0,0.85);;\r\n}\r\n.text {\r\n  color: rgb(74,74,74);\r\n  font-size: 16px;\r\n  line-height: 24px;\r\n  text-indent: 32px;\r\n}\r\n.text .fill {\r\n  color: black;\r\n  padding: 0 3px;\r\n}\r\n\r\n.table-box {\r\n  padding-top: 10px;\r\n  padding-bottom: 10px;\r\n}\r\n.table__title {\r\n  font-size: 14px;\r\n  color: rgba(0,0,0,0.85);\r\n  padding-bottom: 10px;\r\n  text-align: center;\r\n}\r\n.table {\r\n  width: 100%;\r\n  text-align: center;\r\n  border: 1px solid rgb(222,222,222);\r\n  border-radius: 4px;\r\n  border-collapse: collapse;\r\n}\r\n.table__td {\r\n  border: 1px solid rgb(222,222,222);\r\n  color: rgb(38,38,38);\r\n  font-size: 16px;\r\n  padding: 8px 0;\r\n}\r\n.table__td-down,.table__td-up {\r\n  font-size: 12px;\r\n  text-align: center;\r\n  width: 90px;\r\n}\r\n.font-size-14 .table__td {\r\n  font-size: 14px;\r\n}\r\n.td__quantile-group {\r\n  padding: 8px 0;\r\n  display: table;\r\n  width: 100%;\r\n}\r\n.td__quantile-group .td__quantile {\r\n  display: table-row;\r\n}\r\n.td__quantile-group .td__quantile:last-of-type {\r\n  border-bottom: none;\r\n}\r\n.quantile__label {\r\n  display: table-cell;\r\n  color: rgb(122,122,122);\r\n  font-size: 14px;\r\n  width: 50%;\r\n}\r\n.quantile__label.quantile__label--ratio {\r\n  width: 60%;\r\n}\r\n.quantile__value {\r\n  display: table-cell;\r\n  width: 50%;\r\n  font-size: 14px;\r\n  text-align: left;\r\n  vertical-align: middle;\r\n}\r\n.quantile__value.quantile__value--ratio {\r\n  width: 40%;\r\n}\r\n.quantile__label .quantile__point {\r\n  margin-right: 10px;\r\n  width: 6px;\r\n  height: 6px;\r\n  display: inline-block;\r\n  margin-bottom: 3px;\r\n  border-radius: 50%;\r\n}\r\n.label-box {\r\n  padding-right: 15px;\r\n  text-align: right;\r\n}\r\n.quantile__point.quantile__point--p50 {\r\n  background-color: rgb(35,191,154);\r\n}\r\n.quantile__point.quantile__point--p90 {\r\n  background-color: rgb(255,162,0);\r\n}\r\n.quantile__point.quantile__point--p99 {\r\n  background-color: rgb(236,127,106);\r\n}\r\n.table__th {\r\n  height: 47px;\r\n  border: 1px solid rgb(222,222,222);\r\n  background-color: rgb(250,250,250);\r\n  color: rgb(102,102,102);\r\n  font-weight: normal;\r\n  font-size: 14px;\r\n}\r\n.table__footer {\r\n  font-size: 14px;\r\n  margin-top: 20px;\r\n  color: rgb(102,102,102);\r\n}\r\n.table__footer .footer__label {\r\n  color: rgb(51,51,51);\r\n}\r\n.table.table-contain-echarts {\r\n  margin-top: 20px;\r\n  margin-bottom: 4px;\r\n}\r\n.table.table-contain-echarts .echarts-box {\r\n  height: 200px;\r\n}\r\n.table.table-contain-echarts .echarts__canvas {\r\n  height: 100%;\r\n}\r\n.echarts {\r\n  height: 100%;\r\n}\r\n.echarts-box .echarts__canvas {\r\n  height: 100%;\r\n}\r\n.echarts.pie-style {\r\n  width: 48%;\r\n  display: inline-block;\r\n}\r\n.echarts__canvas.echarts__line {\r\n  width: 1100px;\r\n  height: 400px;\r\n}\r\n.echarts__canvas.echarts__line-and-bar {\r\n  width: 1100px;\r\n  height: 400px;\r\n}\r\n.echarts__canvas.echarts__sankey {\r\n  width: 1100px;\r\n  height: 400px;\r\n}\r\n.table__td.echarts__td-bar {\r\n  width: 31%;\r\n}\r\n.echarts.echarts__bar {\r\n  width: 31%;\r\n  height: 280px;\r\n  display: inline-block;\r\n}\r\n.echarts.echarts__bar-value {\r\n  width: 48%;\r\n  height: 280px;\r\n  display: inline-block;\r\n}\r\n.echarts__canvas.echarts__pie {\r\n  width: 545px;\r\n  height: 280px;\r\n}\r\n.echarts__legends {\r\n  text-align: center;\r\n  margin-bottom: 5px;\r\n}\r\n.echarts__legend:nth-of-type(1),.echarts__legend:nth-of-type(2) {\r\n  margin-right: 10px;\r\n}\r\n.color-block {\r\n  width: 16px;\r\n  height: 8px;\r\n  border-radius: 2px;\r\n  margin-right: 4px;\r\n  display: inline-block;\r\n}\r\n.color-block.blue {\r\n  background-color: rgb(88,176,209);\r\n}\r\n.color-block.green {\r\n  background-color: rgb(140,206,213);\r\n}\r\n.color-block.light-green {\r\n  background-color: rgb(180 208 148);\r\n}\r\n.legend-text {\r\n  font-size: 12px;\r\n  color: rgb(102,102,102);\r\n}\r\n.echarts__title {\r\n  font-size: 14px;\r\n  color: rgba(0,0,0,0.85);\r\n  padding-bottom: 10px;\r\n  text-align: center;\r\n}\r\n.echarts__line-and-bar-title {\r\n  padding-top: 10px\r\n}\r\n', 1, NULL);
